import{_ as l,o,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Code Walkthroughs: CoDel for BlueStore","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: CoDel for BlueStore","date":"2021-11-25T00:00:00.000Z","updated":"2021-11-26T00:00:00.000Z","tags":["Ceph","BlueStore","CoDel算法","分布式存储","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthroughs_-_CoDel_for_BlueStore.md","filePath":"posts/2021/Ceph_Code_Walkthroughs_-_CoDel_for_BlueStore.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Code_Walkthroughs_-_CoDel_for_BlueStore.md"};function i(s,e,u,h,d,_){return o(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议由Ceph分布式存储系统的研发人员主持，主要讨论了BlueStore中的CoDel（Cuddle）算法。会议内容涵盖了问题背景、解决方案架构、代码实现以及实验结果等方面。</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ol><li><p><strong>问题背景</strong>：</p><ul><li>在Ceph系统中，前端（如OSD）和后端（如BlueStore）处理不同的存储任务。当后端队列过大时，会影响系统的可调度性。</li></ul></li><li><p><strong>解决方案架构</strong>：</p><ul><li>引入CoDel算法，通过智能的准入控制机制，平衡前端可调度性和后端吞吐量。</li><li>CoDel算法包含高频循环（快速循环）和低频循环（慢速循环），分别控制请求的准入和参数优化。</li></ul></li><li><p><strong>代码实现</strong>：</p><ul><li>主要代码位于<code>blueStore_slow_fast_cuddle.cc</code>和<code>blueStore_slow_fast_cuddle.h</code>文件中。</li><li>通过配置文件控制算法的激活和参数设置，并使用定时器触发快速循环和慢速循环。</li></ul></li><li><p><strong>实验结果</strong>：</p><ul><li>使用FIO生成工作负载，在SSD上进行实验。</li><li>实验表明，CoDel算法能够有效控制目标延迟参数，适应不同的工作负载变化。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认CoDel算法的有效性，并计划将其集成到Ceph的BlueStore中。</li><li>计划进一步研究CoDel算法对前端调度和队列服务质量的影响。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>将会议内容和实验结果整理成文档，添加到相关Pull Request中。</li><li>优化CoDel算法，特别是在混合IO大小等复杂场景下的性能。</li><li>定期回顾和讨论CoDel算法的进展，确保其持续改进和适应新的需求。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>CoDel算法的设计和实现细节为后续研究和开发提供了重要参考。</li><li>会议讨论了CoDel算法在实际应用中的潜在影响，特别是在提高系统可调度性和服务质量方面的潜力。</li></ul>',11)])])}const C=l(r,[["render",i]]);export{p as __pageData,C as default};
